    """Checks if S(n)S(n+1)...S(n+37) is divisible by 11."""
    for k in range(38):
        digit_sum = S(n + k)
        if digit_sum % 11 == 0:
            # The product is divisible by 11
            return False
    # The product is not divisible by 11
    return True

